from functools import lru_cache

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @lru_cache(None)
        def dp(i: int, carry: int) -> int:
            remaining = n - i

            if carry == -1:
                if remaining == 0:
                    return 0
                if remaining == 1:
                    return nums[i]
                if remaining == 2:
                    return max(nums[i], nums[i + 1])

                a, b, c = nums[i], nums[i + 1], nums[i + 2]
                return min(
                    max(a, b) + dp(i + 3, c),
                    max(a, c) + dp(i + 3, b),
                    max(b, c) + dp(i + 3, a),
                )

            if remaining == 0:
                return carry
            if remaining == 1:
                return max(carry, nums[i])

            a, b = nums[i], nums[i + 1]
            return min(
                max(carry, a) + dp(i + 2, b),
                max(carry, b) + dp(i + 2, a),
                max(a, b) + dp(i + 2, carry),
            )

        return dp(0, -1)
